/* ingles do menu para algumas opcoes (o options.txt fala em numeros) */
static const char* const k_en_help[][2] = {
    { "faster_pause_menu", "On: pause menu animations (opening, closing and turning pages) run twice as fast, like Majora's Mask. Off: like the original." },
    { "faster_bottle_empty", "On: emptying a bottle (fish, bugs, fairy, blue fire...) is 3 times faster. Off: like the original." },
    { "faster_rupee_counter", "On: the rupee counter moves 10 at a time when you get or spend a lot (no waiting for the count). Off: like the original." },
    { "faster_shadow_ship", "On: the Shadow Temple boat moves much faster while you are aboard and no Stalfos is near. Off: like the original." },
    { "rebottle_blue_fire", "On: blue fire you released from a bottle can be caught again. Off: like the original (it is lost)." },
    { "no_heart_animation", "On: the heart being filled on the life meter does not pulse. Off: like the original." },
    { "disable_title_card", "On: the area name does not show when you enter a place. Off: like the original." },
    { "dampe_all_night", "On: Dampe the gravekeeper is in the graveyard all night (not only from 6 to 9 pm) and his hut is open. Off: like the original." },
    { "daytime_gold_skulltulas", "On: the Gold Skulltulas that only appear at night also appear during the day. Off: like the original." },
    { "shops_open_all_hours", "On: shops and games that only open by day or only by night (Bombchu shop, chest game, potion shop, mask shop, bazaars, Kakariko archery...) are always open. Off: like the original." },
    { "fast_drops", "On: ammo and items dropped by bushes, rocks and enemies are picked up without the 'you got' scene, even the first time. Pieces of Heart and keys keep the scene. Off: like the original." },
    { "skip_navi_forced_talk", "On: Navi does not stop Link to talk when you enter some places. Navi's hints on her button stay. Off: like the original." },
    { "skip_npc_forced_talk", "On: characters and notices that stop Link to talk when he gets close (hidden area messages, the Gerudo who hands over the card, Goron Link rolling) no longer do. Off: like the original." },
    { "skip_warp_cutscenes", "On: warp songs take you straight to the destination, without the departure scene (rising lights) or the arrival scene. Off: like the original." },
    { "skip_jabu_fish", "On: Lord Jabu-Jabu opens his mouth when you get close, no fish needed. Off: like the original." },
    { "skip_child_stealth", "On: the crawlspace at the entrance of Hyrule Castle (child Link) goes straight to Zelda's courtyard, without sneaking past the guards. Off: like the original." },
    { "skip_tower_escape", "On: after defeating Ganondorf, go straight to the final battle, without the escape from the collapsing tower. Off: like the original." },
    { "market_sneak", "On: at night, the guard at the Market entrance asks child Link if he wants to go out for a walk; yes takes you to Hyrule Field (without a mask on). Off: like the original (only in the morning)." },
    { "arrow_cycle", "On: while aiming the bow (adult), R1 switches the arrow: normal, fire, ice and light (only the ones you have, with enough magic). Magic is spent when the arrow is shot. Off: like the original." },
    { "bow_reticle", "On: aiming the bow or the slingshot shows a red dot where the shot will land, like the Hookshot. Off: like the original." },
    { "hookshot_reticle_color", "On: the Hookshot dot turns green on surfaces it can grab and stays red on the others. Off: like the original (always red)." },
    { "time_travel", "On: with the Ocarina of Time, playing the Song of Time away from the places where it already does something (time blocks, Door of Time, frogs, gossip stones) switches Link's age, and he comes back in the same place. Off: like the original." },
    { "pause_warp", "On: with an ocarina, A on a learned warp song in the Quest page of the menu closes the menu, plays the song and asks whether to warp. Off: like the original." },
    { "mask_select", "On: after paying for all the masks of the shop, A on the mask in the item menu switches to the next one, without going back to the shop. Off: like the original." },
    { "mm_bunny_hood", "On: with the Bunny Hood, Link runs 1.5x faster, like in Majora's Mask, and characters don't react to it. Off: like the original." },
    { "ask_to_equip", "On: when Link gets a sword, shield or tunic he can use, the game asks whether to equip it now. Off: like the original." },
    { "minimal_ui", "On: with the minimap off (SELECT+L1), the buttons (with their items), rupees and keys are hidden; hearts only show when not full and magic only while it is being used. Turning the minimap on shows everything. Takes effect from the next area. Off: like the original." },
    { "light_hit_marks", "On: the flash when the sword hits an enemy or a liftable rock is drawn only where the image has something, and the last almost-empty frames of its animation are skipped. Lighter in combat, looks the same. Off: like the original." },
    { "fast_magnified_textures", "On: textures seen up close, stretched over several pixels (sky, walls up close, fire, smoke), are read on half of the pixels; the ones in between are the average of their neighbors. Lighter, and the image looks almost the same. Off: every pixel, like before." },
    { "lens_flare", "On: like the original. When you look at the sun, colored circles and a glare appear on screen (the reflection on the camera lens). Off: without them; the game runs lighter when looking at the sun, because the circles and the glare cover a good part of the screen with transparency." },
    { "menu_theme", "Colors of this menu and of the short notices (state saved...): dark green and gold, or light (lime green, white and navy)." },
    { "language", "Language of the game and of this menu: English (original), Brazilian Portuguese (Zelda 64 BR fan translation), Japanese (the original Japanese text, also in the US cartridge), German or French (these two come from the European ROM: put the \"(Europe) (En,Fr,De) (Rev A)\" ROM, the .zip works too, in the game folder once) Italian (Zelda 64 ITA fan translation by XXcentury) or Spanish (fan translation by eduardo_a2j). The game restarts to change it." },
    { "sleeping_waterfall", "Waterfall at the entrance of Zora's Domain. Always play the song: like the original, play Zelda's Lullaby every time. Play once: after the first time it stays open. Not needed: it opens by itself once you know the song and have an ocarina." },
    { "retro_filter", "CRT TV look. Scanlines: dark lines between the lines of the picture. Scanlines + mask: also the red, green and blue column mask of a TV screen. With the filter, the game is drawn at 320x240 like the N64 and every game line takes 2 screen lines, so the filter's lines match the game's (the maximum resolution is not used). Since the lines darken the picture, turning it on raises the brightness by itself (3 with scanlines, 4 with the mask; you can still change it as usual), and turning it off brings back the brightness from before." },
    { "screen_contrast", "Contrast of the screen, like Tweaks > Display in OnionOS (the same 0 to 20 scale). \"system\" = your OnionOS setting. It only changes while the game is open: when you quit, the screen goes back to the system's. No performance cost." },
    { "screen_hue", "Hue (color tint) of the screen, like Tweaks > Display in OnionOS (the same 0 to 20 scale). \"system\" = your OnionOS setting. It only changes while the game is open: when you quit, the screen goes back to the system's. No performance cost." },
    { "screen_saturation", "Color saturation of the screen, like Tweaks > Display in OnionOS (the same 0 to 20 scale). \"system\" = your OnionOS setting. It only changes while the game is open: when you quit, the screen goes back to the system's. No performance cost." },
    { "camera_distance", "Distance of the camera that follows Link (walking, Z, jumping, swimming, targeting), in % of the original: 70 = closer, 130 = farther. Cutscenes and the fixed cameras of some rooms stay as in the original. A farther camera shows more of the scene (a bit more work to draw). Applies when the camera changes mode (stopping, running, Z...)." },
    { "retro_filter_strength", "How much the retro filter's lines (and mask) darken the picture: 25% to 75% (50 = default). Only with the filter on." },
    { "dither", "Color dithering: hides the color bands in gradients (sky, fog, dark places). Uniform: a subtle pattern on surfaces only (default). Like the console: the pattern the game asks for, everywhere. Off: no dithering (bands show)." },
    { "texture_filter", "Texture smoothing. Light: fast and almost the same as the N64 (default). 4x4 table: a bit smoother, uses more memory. Exact: the same as the N64, but slower. The game restarts to change it." },
    { "close_filter_mode", "Smoothing of textures very close to the camera (see the option above). Exact (N64): the smoothest, a bit slower. 4x4 table: faster, slightly blocky. The game restarts to change it." },
    { "cheat_deku_stick", "Unbreakable: Deku Sticks don't break. Unbreakable, on fire: they also stay lit. Off: like the original." },
    { "exact_filter_close", "Textures very close to the camera look blocky with the Light smoothing. With a number, those textures (where one texture pixel covers that many screen pixels or more) use the up-close filter below. \"off\" turns it off. The game restarts to change it." },
    { "autosave", "The game saves by itself (like Save in the pause menu) every that many minutes of play, and when you quit. A short notice shows. \"off\" turns it off." },
    { "dpad_smooth_turn", "With a number, Link turns gradually when you change the D-pad direction, in smooth curves like an analog stick. Higher = smoother (70 = default). \"off\": the 8 fixed D-pad directions." },
    { "sprint_speed", "Sprint: A makes Link roll; keep holding A after the roll and he runs faster (150 = 1.5x the normal speed). Release A or stop to walk normally. \"off\" turns it off." },
};

